Q: Why isn&#39;t this emitting the message? A: <p>Using dynamic namespaces with Flask-SocketIO is not possible. However, you can use static namespaces and rooms.</p>
<p>Based on your example code, it's difficult to understand your requirements.</p>
<p>The following simple example demonstrates the use of rooms in the standard namespace. A maximum of two people can meet and send messages in a room. The room name is generated randomly.</p>
<pre class="lang-py prettyprint-override"><code>&quot;&quot;&quot; 
Required package installations:
% pip install flask flask-session flask-socketio 
&quot;&quot;&quot;

from flask import Flask, render_template, request, session
from flask_session import Session
from flask_socketio import SocketIO, join_room, leave_room, emit
import random, string

app = Flask(__name__)
app.config.from_mapping(
    SECRET_KEY='your secret here', 
    SESSION_TYPE='filesystem' 
)
socketio = SocketIO(app)

rooms = {}

def generate_room_code(length, existing_codes):
    while True:
        code_chars = random.choices(string.ascii_letters, k=length)
        code = ''.join(code_chars)
        if code not in existing_codes:
            return code

@app.route('/')
def index():
    session.clear()
    return render_template('index.html') 

@socketio.on('disconnect')
def on_disconnect():
    username = session.get('name')
    room = session.get('room')
    if username is None or room is None:
        return

    leave_room(room)
    rooms[room]['members'] -= 1
    if rooms[room]['members'] &lt;= 0:
        del rooms[room]

    session.pop('room')

    emit('message', {'msg': f'{username} has left room {room}'}, room=room)

@socketio.on('join')
def on_join(data):
    username = data['username']
    room = data['roomname']
    if not room or room not in rooms or rooms[room]['members'] &gt;= 2:
        room = generate_room_code(6, list(rooms.keys()))
        rooms[room] = {
            'members': 0
        } 
    rooms[room]['members'] += 1
    join_room(room) 
    session['room'] = room
    session['name'] = username

    emit('message', {'msg': f'{username} has joined room {room}'}, room=room)

@socketio.on('leave')
def on_leave(data):
    username = session.get('name')
    room = session.get('room')
    if username is None or room is None:
        return

    leave_room(room)
    rooms[room]['members'] -= 1
    if rooms[room]['members'] &lt;= 0:
        del rooms[room]

    session.pop('room')

    emit('message', {'msg': f'{username} has left room {room}'}, room=room)

@socketio.on('send_message')
def room_message(data):
    room = session.get('room')
    if room is None:
        return

    msg = data['message']
    emit('message', {'msg': msg}, room=room)

if __name__ == &quot;__main__&quot;:
    socketio.run(app, debug=True)
</code></pre>
